// STS2 relic model (T4 run layer): id/rarity table generated from the decompiled source
// plus the combat-visible relic effects the engine implements.
//
// The table (Sts2RelicIds.h / Sts2RelicTable.cpp) is generated by
// engine/tools/gen_sts2_relics.py. Relics outside the implemented effect set can still be
// owned and bought — they simply have no engine effect yet (RELIC_EFFECT_NONE).

#ifndef STS2_RELIC_H
#define STS2_RELIC_H

#include "sts2/Sts2Battle.h"
#include "sts2/Sts2Ids.h"

namespace sts2 {

// RelicRarity order matches the game enum (None, Starter, Common, Uncommon, Rare, Shop,
// Event, Ancient); the shop pulls from Common/Uncommon/Rare/Shop only.
enum class RelicRarity : std::uint8_t {
    NONE = 0, STARTER, COMMON, UNCOMMON, RARE, SHOP, EVENT, ANCIENT,
};
constexpr int RELIC_RARITY_COUNT = 8;

enum class RelicEffect : std::uint8_t {
    RELIC_EFFECT_NONE = 0,
    RELIC_POWER_SELF,       // apply `power` to the player at combat start (Vajra/Stone/Scales)
    RELIC_BLOCK,            // gain `amount` unpowered block at combat start (Anchor)
    RELIC_VULNERABLE_ALL,   // Vulnerable `amount` to every hittable enemy at combat start
    RELIC_DRAW,             // +amount cards in the opening hand draw (Bag of Preparation)
    RELIC_ENERGY,           // +amount energy on the first turn (Lantern)
    RELIC_ENDTURN_BLOCK,    // gain `amount` block at end of turn when the player has none
    RELIC_POST_COMBAT_HEAL, // heal `amount` after a combat win (Burning Blood)
};

struct RelicDef {
    RelicId id = RelicId::INVALID;
    const char* name = "NONE";
    RelicRarity rarity = RelicRarity::NONE;
    bool ironcladPool = false;
    bool sharedPool = false;
    bool allowedInShops = true;
    RelicEffect effect = RelicEffect::RELIC_EFFECT_NONE;
    PowerId power = PowerId::NONE;
    int amount = 0;
};

const RelicDef& sts2RelicDef(RelicId id);
const char* sts2RelicName(RelicId id);

} // namespace sts2

#endif // STS2_RELIC_H
